import { readFile } from 'node:fs/promises';
import { Injectable } from '@nestjs/common';
import type { Polygon } from './geometry.js';

/** Municipality boundaries by 6-digit IBGE code, as CNES identifies them. */
export type MunicipalityBoundaries = Map<string, Polygon[]>;

interface BoundariesFile {
  boundaries: Record<string, Record<string, Polygon[]>>;
}

@Injectable()
export class MunicipalityBoundariesClient {
  private file?: Promise<BoundariesFile>;

  /**
   * Reads the simplified boundaries of every municipality of one state from
   * the bundled file, generated by `scripts/generate-municipality-boundaries.mjs`.
   * They are not fetched at runtime because the IBGE host can be unreachable
   * from the server, which would leave every coordinate unchecked.
   */
  async fetch(stateAbbreviation: string): Promise<MunicipalityBoundaries> {
    this.file ??= readFile(
      new URL('./municipality-boundaries.json', import.meta.url),
      'utf8',
    )
      .then((content) => JSON.parse(content) as BoundariesFile)
      .catch((error: unknown) => {
        // A failed read must not be remembered until the next restart.
        this.file = undefined;
        throw error;
      });

    const { boundaries } = await this.file;
    const municipalities = boundaries[stateAbbreviation];
    if (!municipalities) {
      throw new Error(`No boundaries for state ${stateAbbreviation}`);
    }
    return new Map(Object.entries(municipalities));
  }
}
